findings.codeExample:
// Before — no text alternative
Image.asset('logo.png')

// After — describe it
Image.asset('logo.png', semanticLabel: 'Acme logo')

// Or, if purely decorative, hide it from assistive tech
ExcludeSemantics(child: Image.asset('divider.png'))

// Before — a screen reader announces only "button"
IconButton(icon: Icon(Icons.share), onPressed: _share)

// After — give it an accessible name
IconButton(icon: Icon(Icons.share), tooltip: 'Share', onPressed: _share)
